"""Drei eigenständige Transparenzregisterakten; Rendering durch den gemeinsamen Builder."""


def doc(file, title, date, body, **extra):
    return {"file": file, "title": title, "date": date, "body": body, **extra}


def mail(file, title, date, sender, recipient, body):
    return doc(file, title, date, body, **{"from": sender, "to": recipient, "subject": title})


